static int neigh_check_cb ( struct neighbour * n ) { struct atmarp_entry * entry = neighbour_priv ( n ) ; struct clip_vcc * cv ; for ( cv = entry -> vccs ; cv ; cv = cv -> next ) { unsigned long exp = cv -> last_use + cv -> idle_timeout ; if ( cv -> idle_timeout && time_after ( jiffies , exp ) ) { pr_debug ( "releasing vcc %p->%p of entry %p\n" , cv , cv -> vcc , entry ) ; vcc_release_async ( cv -> vcc , - ETIMEDOUT ) ; } } if ( entry -> vccs || time_before ( jiffies , entry -> expires ) ) { return 0 ; } if ( refcount_read ( & n -> refcnt ) > 1 ) { struct sk_buff * skb ; pr_debug ( "destruction postponed with ref %d\n" , refcount_read ( & n -> refcnt ) ) ; while ( ( skb = skb_dequeue ( & n -> arp_queue ) ) != NULL ) { dev_kfree_skb ( skb ) ; } return 0 ; } pr_debug ( "expired neigh %p\n" , n ) ; return 1 ; } 